<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$invoices=$db->query("SELECT i.*,COALESCE(c.name,l.name,'Unknown') client_name,COALESCE(c.email,l.email) client_email FROM invoices i LEFT JOIN clients c ON c.id=i.client_id LEFT JOIN leads l ON l.id=i.lead_id ORDER BY i.created_at DESC")->fetchAll();function money2($v,$c){return $c.' '.number_format((float)$v,2);} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Invoices</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2">Invoices & Payments</h1><p class="text-muted">Manage billing and client payments.</p></div><div><a class="btn btn-outline-dark me-2" href="financial-dashboard.php">Financial Dashboard</a><a class="btn btn-dark" href="invoice-form.php">+ New Invoice</a></div></div><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Invoice</th><th>Client</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th><th>Due</th><th></th></tr></thead><tbody><?php foreach($invoices as $i):?><tr><td><strong><?=$e($i['invoice_number'])?></strong><div class="small text-muted"><?=$e($i['title'])?></div></td><td><?=$e($i['client_name'])?><div class="small text-muted"><?=$e($i['client_email'])?></div></td><td><?=money2($i['total'],$i['currency'])?></td><td><?=money2($i['amount_paid'],$i['currency'])?></td><td><?=money2($i['balance_due'],$i['currency'])?></td><td><span class="badge text-bg-secondary"><?=ucfirst($e($i['status']))?></span></td><td><?=$e($i['due_date']?:'—')?></td><td><a class="btn btn-sm btn-outline-dark" target="_blank" href="invoice-view.php?token=<?=$e($i['public_token'])?>">View</a><?php if((float)$i['balance_due']>0):?> <a class="btn btn-sm btn-outline-secondary" href="invoice-payment.php?id=<?=$i['id']?>">Payment</a><?php endif;?></td></tr><?php endforeach;?><?php if(!$invoices):?><tr><td colspan="8" class="p-4 text-muted">No invoices yet.</td></tr><?php endif;?></tbody></table></div></div></main></body></html>